<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class Teacher extends Model{protected $fillable=['department_id','name','slug','position','bio','photo','education','qualification','experience_years','awards','sort','is_active'];protected $casts=['is_active'=>'boolean'];public function performances(){return $this->belongsToMany(EventPerformance::class,'event_performance_teachers')->withPivot(['role','sort'])->where('event_performances.is_published',true)->with(['event','media','students','guests'])->whereHas('event',fn($q)=>$q->where('is_published',true));}public function students(){return $this->hasMany(Student::class)->where('is_active',true)->orderBy('sort')->orderBy('name');}public function department(){return $this->belongsTo(Department::class);}public function getRouteKeyName(){return 'slug';}}